content.content:
1	---
2	import Layout from '@/layouts/base.astro';
3	import GatedQuizStepper from '@/components/quiz/GatedQuizStepper';
4	import QuizIcon from '@/lib/quiz-engine/components/QuizIcon';
5	import QuizIntroCard from '@/lib/quiz-engine/components/QuizIntroCard';
6	import Logo from '@/assets/images/global/APR-Logo-2020_Horizontal_RGB.svg';
7	import { Image } from 'astro:assets';
8	import { getCollection, getEntry } from 'astro:content';
9	
10	export async function getStaticPaths() {
11	  const quizzes = await getCollection('quizzes');
12	  return quizzes.map((quiz) => ({ params: { slug: quiz.id } }));
13	}
14	
15	const { slug } = Astro.params;
16	const entry = await getEntry('quizzes', slug!);
17	if (!entry) {
18	  return new Response(null, { status: 404, statusText: 'Not found' });
19	}
20	
21	const data = entry.data;
22	const persuasionParagraphs = data.persuasion
23	  ? data.persuasion
24	      .split(/\n\s*\n/)
25	      .map((p: string) => p.trim())
26	      .filter(Boolean)
27	  : [];
28	const persuasionBullets = data.persuasionBullets ?? [];
29	const howItWorks = data.howItWorks ?? [];
30	// Balance the section cards: 3 (or any multiple of 3) reads best as a 3-up row;
31	// everything else stays 2-up (so 4 cards are a tidy 2x2 rather than 3+1).
32	const sectionColsClass =
33	  data.sections.length % 3 === 0 ? 'md:grid-cols-3' : 'md:grid-cols-2';
34	// Reflective (map-move) quizzes have no "right" answer, so suppress the
35	// correct/incorrect highlighting the band quizzes use.
36	const showCorrectness = (data.resultStyle ?? 'band') !== 'map-move';
37	const heroButtonLabel = data.heroButtonLabel ?? 'Start the quiz';
38	// Says when the email is asked for, which differs by `capturePosition`, so the
39	// hero never promises "at the end" on a quiz that gates at the start.
40	const heroButtonNote =
41	  data.heroButtonNote ??
42	  (data.capturePosition === 'start'
43	    ? 'Free. You’ll add your email before you start.'
44	    : 'Free. To see your results, you’ll add your email at the end.');
45	// A start-gated quiz puts the opt-in panel on the cover itself, so the cover
46	// needs no CTA button of its own: the panel is the call to action.
47	const showHeroButton = data.capturePosition !== 'start';
48	
49	// Tints for the "how it works" chips. Colour here is warmth and sequence only,
50	// so it is deliberately kept out of the semantic roles the result page uses.
51	const stepToneClasses: Record<string, string> = {
52	  accent: 'bg-quiz-accent-tint text-quiz-accent-strong',
53	  valuable: 'bg-quiz-valuable-tint text-quiz-valuable-strong',
54	  slipping: 'bg-quiz-slipping-tint text-quiz-slipping-strong',
55	  alt: 'bg-quiz-step3-tint text-quiz-step3-strong',
56	};
57	const stepLabelClasses: Record<string, string> = {
58	  accent: 'text-quiz-accent-strong',
59	  valuable: 'text-quiz-valuable-strong',
60	  slipping: 'text-quiz-slipping-strong',
61	  alt: 'text-quiz-step3-strong',
62	};
63	---
64	
65	<Layout
66	  title={data.title}
67	  description={data.description ?? data.title}
68	  includeCoursesCTA={false}
69	  hideChrome={true}
70	>
71	  <div class="bg-quiz-page min-h-screen">
72	    <header class="border-quiz-hairline border-b-[0.5px]">
73	      <div class="mx-auto max-w-170 px-4 py-3">
74	        <a href="/" aria-label="Agile Pain Relief home">
75	          <img src={Logo.src} alt="Agile Pain Relief" class="h-9 w-auto" />
76	        </a>
77	      </div>
78	    </header>
79	
80	    <div class="mx-auto max-w-170 px-4 py-10 md:py-14">
81	      <div data-quiz-chrome>
82	        <section class="mb-8">
83	          <h1
84	            class="text-quiz-ink max-w-[32ch] text-3xl/tight font-bold md:text-4xl/tight"
85	          >
86	            {data.heroHeading ?? data.title}
87	          </h1>
88	          {
89	            data.heroBody ? (
90	              <p class="text-quiz-ink-secondary mt-4 max-w-[52ch] text-base/relaxed">
91	                {data.heroBody}
92	              </p>
93	            ) : null
94	          }
95	          {
96	            persuasionParagraphs.map((paragraph) => (
97	              <p class="text-quiz-ink-muted mt-3 max-w-[52ch] text-base/relaxed">
98	                {paragraph}
99	              </p>
100	            ))
101	          }
102	          {
103	            showHeroButton ? (
104	              <div class="mt-7">
105	                <button
106	                  type="button"
107	                  data-quiz-start
108	                  class="bg-quiz-ink focus:ring-quiz-accent-strong rounded-lg px-5 py-2.5 text-base font-medium text-white transition hover:opacity-90 focus:ring-2 focus:ring-offset-2 focus:outline-none"
109	                >
110	                  {heroButtonLabel}
111	                </button>
112	                {heroButtonNote ? (
113	                  <p class="text-quiz-ink-muted mt-3 text-sm">
114	                    {heroButtonNote}
115	                  </p>
116	                ) : null}
117	              </div>
118	            ) : null
119	          }
120	        </section>
121	
122	        {/* What the taker gets, shown before they hand anything over. */}
123	        {
124	          howItWorks.length > 0 ? (
125	            <section
126	              class="mb-8 grid gap-3.5"
127	              style="grid-template-columns: repeat(auto-fit, minmax(180px, 1fr))"
128	            >
129	              {howItWorks.map((step) => (
130	                <div class="border-quiz-hairline bg-quiz-card rounded-xl border-[0.5px] p-4">
131	                  <span
132	                    class:list={[
133	                      'mb-3 flex size-10 items-center justify-center rounded-[10px]',
134	                      stepToneClasses[step.tone] ?? stepToneClasses.accent,
135	                    ]}
136	                  >
137	                    <QuizIcon name={step.icon ?? ''} size={22} />
138	                  </span>
139	                  {step.label ? (
140	                    <p
141	                      class:list={[
142	                        'mb-1 text-sm',
143	                        stepLabelClasses[step.tone] ?? stepLabelClasses.accent,
144	                      ]}
145	                    >
146	                      {step.label}
147	                    </p>
148	                  ) : null}
149	                  <h3 class="text-quiz-ink text-lg font-bold">{step.title}</h3>
150	                  {step.body ? (
151	                    <p class="text-quiz-ink-secondary mt-1 text-sm/relaxed">
152	                      {step.body}
153	                    </p>
154	                  ) : null}
155	                </div>
156	              ))}
157	            </section>
158	          ) : null
159	        }
160	
161	        {
162	          /* Section cards and proof bullets are the pre-"how it works" cover
163	            layout, kept for quizzes that don't declare a steps strip. */
164	        }
165	        {
166	          howItWorks.length === 0 && data.sections.length > 0 ? (
167	            <section class="mb-8">
168	              {data.categoriesHeading ? (
169	                <h2 class="text-quiz-ink mb-5 text-2xl font-bold">
170	                  {data.categoriesHeading}
171	                </h2>
172	              ) : null}
173	              <div class:list={['grid grid-cols-1 gap-3.5', sectionColsClass]}>
174	                {data.sections.map((section) => (
175	                  <div class="border-quiz-hairline bg-quiz-card rounded-xl border-[0.5px] p-4">
176	                    {section.image ? (
177	                      typeof section.image === 'string' ? (
178	                        <img
179	                          src={section.image}
180	                          alt=""
181	                          class="mb-3 h-24 w-full rounded-lg object-contain"
182	                          loading="lazy"
183	                        />
184	                      ) : (
185	                        <Image
186	                          src={section.image}
187	                          alt=""
188	                          class="mb-3 h-24 w-full rounded-lg object-contain"
189	                          loading="lazy"
190	                        />
191	                      )
192	                    ) : null}
