  heading,
  email,
  onEmailChange,
  onSubmit,
  submitting,
  canSubmit,
  submitButtonLabel,
  footnote,
  error,
  extras,
}: CaptureFieldProps & { heading: string }) {
  return (
    <form
      onSubmit={onSubmit}
      className="bg-quiz-context-panel rounded-xl p-4 md:p-5"
      noValidate
    >
      <label
        htmlFor="quiz-email"
        className="text-quiz-ink-secondary mb-2 block text-base"
      >
        {heading}
      </label>
      <div className="flex flex-col gap-2.5 sm:flex-row">
        <input
          id="quiz-email"
          type="email"
          autoComplete="email"
          required
          placeholder="name@work.com"
          value={email}
          onChange={(e) => onEmailChange(e.target.value)}
          className="border-quiz-hairline bg-quiz-card text-quiz-ink placeholder:text-quiz-ink-muted focus:border-quiz-accent-edge focus:ring-quiz-accent-edge min-w-0 flex-1 rounded-lg border-[0.5px] px-3.5 py-2.5 text-base focus:ring-1 focus:outline-none"
        />
