        <p className="text-quiz-slipping-strong mt-3 text-sm" role="alert">
          {error}
        </p>
      ) : null}

      <p className="text-quiz-ink-muted mt-2.5 text-sm">{footnote}</p>
    </form>
  );
}

/** The end-of-quiz capture: a standalone card once the questions are done. */
