import "./load-env";
import { NEWSLETTER_SUBSCRIBERS_LIST_ID } from "../../shared/cakemail-constants";
import { CakemailClient } from "./cakemail-client";

/**
 * One-shot: register the custom attributes used by the Newsletter Subscribers
 * list. Run after the initial Cakemail setup and any time a new attribute is
 * added to the plan.
 *
 * This wraps migration-doc Step 3 (§Cakemail prep) for the Newsletter
 * Subscribers list: `firstname`, `lastname`, and the Drip migration cohort
 * markers.
 */

async function main() {
  const client = new CakemailClient();
  await client.ensureCustomAttributes(NEWSLETTER_SUBSCRIBERS_LIST_ID, [
    { name: "firstname", type: "text" },
    { name: "lastname", type: "text" },
    { name: "drip_migrated", type: "text" },
    { name: "migrated_at", type: "text" },
  ]);
  console.log(
    `Custom attributes ensured on Newsletter Subscribers list (${NEWSLETTER_SUBSCRIBERS_LIST_ID}): firstname, lastname, drip_migrated, migrated_at`,
  );
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

