import QuizIcon from './QuizIcon';

interface Props {
  title?: string;
  body?: string;
  /** Icon in the chip above the heading. */
  icon?: string;
  /**
   * Renders a button under the copy. Omit both to render the card as a static
   * block, which is what a start-gated quiz does: the reassurance sits on the
   * cover above the opt-in, and the opt-in's own button is the only action.
   */
  buttonLabel?: string;
  onStart?: () => void;
}

/**
 * The "before you start" reassurance card. Shared so the same card can be a
 * step in the stepper (end-capture quizzes) or a static block on the host
 * page's cover (start-gated quizzes), without two copies of the styling.
 *
 * The card fills the reading column like every other block, but its centred
 * text is held to a shorter measure inside it: centred lines get hard to track
 * much past ~46 characters.
 */
export default function QuizIntroCard({
  title,
  body,
  icon = 'privacy',
  buttonLabel,
  onStart,
}: Props) {
  return (
    <div className="border-quiz-hairline bg-quiz-card rounded-xl border-[0.5px] p-6 text-center md:p-8">
      <div className="mx-auto max-w-[46ch]">
        <span className="bg-quiz-accent-tint text-quiz-accent-strong mx-auto mb-4 flex size-11 items-center justify-center rounded-full">
          <QuizIcon name={icon} size={20} />
        </span>
        {title ? (
          <h2 className="text-quiz-ink text-2xl font-bold">{title}</h2>
        ) : null}
        {body ? (
          <p className="text-quiz-ink-secondary mt-3 text-base/relaxed whitespace-pre-line">
            {body}
          </p>
        ) : null}
        {buttonLabel && onStart ? (
          <button
            type="button"
            onClick={onStart}
            className="bg-quiz-ink focus:ring-quiz-accent-strong mt-6 rounded-lg px-5 py-2.5 text-base font-medium text-white transition hover:opacity-90 focus:ring-2 focus:ring-offset-2 focus:outline-none"
          >
            {buttonLabel}
          </button>
        ) : null}
      </div>
    </div>
  );
}

